const origin = ($json.origin || '').replace(/\/$/, '');
// Scan the origin only. nuclei's exposure/misconfig/default-login templates
// probe their own known paths off the base URL (that's how /metrics, /.git,
// /actuator etc. get found) - a per-URL fan-out multiplies runtime into the
// tens of minutes for little extra coverage. CVE/vulnerabilities/panels dirs
// are excluded: thousands of templates, and CVEs come from nmap-vulners +
// the WordPress NVD lookup which this then dedups against.
const q = origin.replace(/'/g, `'\\''`);
const cmd = `timeout 300 nuclei -u '${q}' -jsonl -or -nc -silent -duc -dast=false `
  + `-rl 60 -c 40 -timeout 10 -retries 1 -exclude-tags dos,fuzz,fuzzing-templates -es info,unknown `
  + `-t http/exposures/ -t http/misconfiguration/ -t http/default-logins/ 2>/dev/null || true`;
return [{ json: { nucleiCmd: cmd, origin } }];

const raw = $json.stdout || '';
const rows = [];
for (const line of raw.split(/\r?\n/)) {
  const s = line.trim();
  if (!s || s[0] !== '{') continue;
  let o; try { o = JSON.parse(s); } catch (e) { continue; }
  const info = o.info || {};
  const cls = info.classification || {};
  const cves = ([].concat(cls['cve-id'] || [])).map(c => String(c).toUpperCase());
  rows.push({
    templateId: o['template-id'] || o.templateID || 'unknown',
    name: info.name || o['template-id'] || 'unknown',
    severity: String(info.severity || 'unknown').toLowerCase(),
    tags: [].concat(info.tags || []).map(t => String(t).toLowerCase()),
    cve: cves[0] || null,
    cves,
    cvss: cls['cvss-score'] || null,
    matchedAt: o['matched-at'] || o.host || null,
    type: o.type || 'http',
  });
}

const seen = new Set();
const findings = [];
for (const f of rows) {
  const k = f.templateId + '|' + f.matchedAt;
  if (seen.has(k)) continue;
  seen.add(k);
  findings.push(f);
}
const order = { critical: 0, high: 1, medium: 2, low: 3, unknown: 4, info: 5 };
findings.sort((a, b) => (order[a.severity] ?? 9) - (order[b.severity] ?? 9));

return [{ json: { ran: true, findings, findingCount: findings.length } }];
